        let bInputs = Inputs.vectors(H.Vector.self, seed: 0xF97F_2AAD_2B80_D1BA)
        let cInputs = Inputs.vectors(H.Vector.self, seed: 0xF97F_29AD_2B80_D007)
        let dInputs = Inputs.vectors(H.Vector.self, seed: 0xF97F_28AD_2B80_CE54)
        for (a, b, c, d) in mixedQuadruples(
            aInputs,
            bInputs,
            cInputs,
            dInputs,
            seed: 0xCB19_602C_467D_22BF
        ) {
            let (_, portLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                unsafe H.appendInterleaved4(a, b, c, d, toUnchecked: &output)
            }
            let (_, referenceLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                H.appendInterleaved4(a, b, c, d, to: &output)
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c)), d: \(describe(d))"
            )
        }
        mismatches.record()
    }
}
